  model: 'google/nano-banana',
  input: {
    prompt: imagePrompt,
    output_format: 'png',
    image_size: '16:9'
  }
};

console.log(`Kie request — prompt: "${imagePrompt.slice(0, 80)}..."`);

return [{ json: { body: JSON.stringify(requestBody) } }];

// Extract the generated image URL from Kie AI result
const data  = $input.first().json;
let kieImageUrl = '';

try {
  const state         = data.data?.state;
  const resultJsonStr = data.data?.resultJson;

  if (state === 'success' && resultJsonStr) {
    const resultData = JSON.parse(resultJsonStr);
    kieImageUrl = resultData.resultUrls?.[0] || '';
  } else {
    console.log(`Kie state: ${state} — continuing without image`);
  }
} catch(e) {
  console.log('Kie parse error: ' + e.message + ' — continuing without image');
}

if (kieImageUrl) {
  console.log('Kie image ready: ' + kieImageUrl);
} else {
  console.log('No Kie image — HCTI will use gradient fallback background');
}

// Merge Kie image URL with all post data needed by Generate Image (HCTI)
const ctx = $('Extract Contra Post').first().json;
return [{ json: { ...ctx, kieImageUrl } }];

// Random delay 0-3 hours (0 to 10800 seconds)
const randomSeconds = Math.floor(Math.random() * 10800);
const hours = Math.floor(randomSeconds / 3600);
const minutes = Math.floor((randomSeconds % 3600) / 60);
console.log(`Random delay: ${hours}h ${minutes}m (${randomSeconds}s)`);
return [{ json: { delaySeconds: randomSeconds, delayLabel: `${hours}h ${minutes}m` } }];

// Get today's day name, date, and detect Sunday
const now = new Date();
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const dayName = days[now.getDay()];
const dateStr = now.toISOString().split('T')[0];
const isSunday = now.getDay() === 0;
console.log(`Today: ${dayName} ${dateStr} | Sunday mode: ${isSunday}`);
return [{ json: { dayName, dateStr, isSunday } }];

// Find topic for today's day
const dayName = $('Get Today').first().json.dayName;
const isSunday = $('Get Today').first().json.isSunday;
const rows = $input.all();
const todayRow = rows.find(r => r.json['Day'] === dayName);

if (!todayRow) {
  throw new Error(`No topic found for ${dayName} in Topic Rotation sheet`);
}

const category = todayRow.json['Category'];
const focus = todayRow.json['Topic Title'] || '';
const angle = todayRow.json['Description / Angle'] || $input.first().json['Content Direction'] || '';

console.log(`Today's topic: ${category} | Focus: ${focus} | Sunday: ${isSunday}`);
return [{ json: { category, focus, angle, dayName, isSunday } }];

// Weekdays: Tavily drives the topic — Content Ideas not used
// Sunday: check Content Ideas for what you built this week
// Any day with explicit High priority override: use it

const isSunday = $('Get Today').first().json.isSunday;
const rows = $input.all();
const category = $('Get Today Topic').first().json.category;

// ── Non-Sunday: only respect explicit High priority override ──────────────
if (!isSunday) {
  const highOverride = rows.find(r => {
    const cat = String(r.json['Category'] || '').trim();
    const status = String(r.json['Status'] || '').trim().toLowerCase();
    const priority = String(r.json['Priority'] || '').trim().toLowerCase();
    return cat === category && status === 'unused' && priority === 'high';
  });

  if (highOverride) {
    console.log(`High priority override found: "${highOverride.json['Idea Title']}"`);
    return [{ json: {
      useIdea: true,
      isSunday: false,
      category,
      ideaTitle: highOverride.json['Idea Title'] || '',
      fullIdea: highOverride.json['Full Idea / Angle'] || '',
      ideaRow: rows.indexOf(highOverride) + 2
    }}];
  }

  // Default for all weekdays: let Tavily find the topic
  console.log(`${category} — Tavily will discover today's topic from trending content`);
  return [{ json: { useIdea: false, isSunday: false, category, ideaTitle: '', fullIdea: '', ideaRow: -1 }}];
}

// ── Sunday: look for "What I Built" idea ────────────────────────────────────
const sundayIdeas = rows.filter(r => {
  const cat = String(r.json['Category'] || '').trim();
  const status = String(r.json['Status'] || '').trim().toLowerCase();
  return cat === 'What I Built' && status === 'unused';
});

const priorityOrder = { 'high': 0, 'medium': 1, 'low': 2 };
sundayIdeas.sort((a, b) => {
  const pa = priorityOrder[String(a.json['Priority'] || 'low').toLowerCase()] ?? 2;
  const pb = priorityOrder[String(b.json['Priority'] || 'low').toLowerCase()] ?? 2;
  return pa - pb;
});

if (sundayIdeas.length > 0) {
  const best = sundayIdeas[0];
  console.log(`Sunday build post: "${best.json['Idea Title']}"`);
  return [{ json: {
    useIdea: true,
    isSunday: true,
    category,
    ideaTitle: best.json['Idea Title'] || '',
    fullIdea: best.json['Full Idea / Angle'] || '',
    ideaRow: rows.indexOf(best) + 2
  }}];
}

console.log('Sunday but no build idea in Content Ideas — will generate general AI insight post');
return [{ json: { useIdea: false, isSunday: true, category, ideaTitle: '', fullIdea: '', ideaRow: -1 }}];

